// === Tab: Block ===
class Block {
  constructor(row, col, id) {
    this.id = id;
    this.col = col;
    this.row = row;
    this.x = map(this.col, 0, segX, paddingX, width - paddingX);
    this.y = map(this.row, 0, segY, paddingY, height - paddingY);
    this.side = gridSize
		this.color = random(currentPalette)
		this.color2 = random(currentPalette)
		while(this.color===this.color2){
			this.color2 = random(currentPalette)
		}
    this.targetX = this.x;
    this.targetY = this.y;
		this.done = false

    this.targetRow = 1;
    this.targetCol = 1;
  }

  showTarget() {
    fill(255);
    textSize(this.side / 2);
    textAlign(CENTER, CENTER);
    text(this.id, this.x + this.side / 2, this.y + this.side / 2);

    fill("#81D893");
    const targetX = map(this.targetCol, 0, segX, paddingX, width - paddingX);
    const targetY = map(this.targetRow, 0, segY, paddingY, height - paddingY);
    text(this.id, targetX + this.side / 2, targetY + this.side / 2);
    // fill(0)

    stroke("#d88181");
    line(
      this.x + this.side / 2,
      this.y + this.side / 2,
      targetX + this.side / 2,
      targetY + this.side / 2
    );
    noStroke();
  }

  draw() {
    this.targetX = map(this.col, 0, segX, paddingX, width - paddingX);
    this.targetY = map(this.row, 0, segY, paddingY, height - paddingY);
    this.x = lerp(this.x, this.targetX, 0.1);
    this.y = lerp(this.y, this.targetY, 0.1);
		noStroke();
    if (debugView) {
      fill("#00000084");
    } else {

    }

		if(this.done == true){
			fill(this.color);
		}else{
			push()
			colorMode(HSB)
			const c = color(0,0,50,0.2)
			pop()
			fill(c)

		}

		rect(this.x, this.y, this.side, this.side, (this.side / 2) * rounded);

		if(this.done == true && strokeView && !debugView){
			fill(bg_color);
			rect(this.x+this.side*0.2, this.y+this.side*0.2, this.side*0.6, this.side*0.6, (this.side*0.6 / 2) * rounded);
		}

  }

  move() {
    if (this.row == this.targetRow && this.col == this.targetCol) {
			this.done = true
      return;
    }else{
			this.done = false
		}
    const dir = this.chooseDir();
    if (dir == "left") {
      this.col--;
    } else if (dir == "right") {
      this.col++;
    } else if (dir == "up") {
      this.row--;
    } else if (dir == "down") {
      this.row++;
    } else {
      this.swapMove(dir);
    }
    updateLocation();
  }

  swap(another) {
    const tempRow = this.row;
    const tempCol = this.col;
    this.row = another.row;
    this.col = another.col;
    another.row = tempRow;
    another.col = tempCol;
  }

  swapMove(dir) {
    for (let anotherBlock of blocks) {
      if (
        dir == "leftSwap" &&
        anotherBlock.col == this.col - 1 &&
        anotherBlock.row == this.row
      ) {
        this.swap(anotherBlock);
        return;
      }
      if (
        dir == "rightSwap" &&
        anotherBlock.col == this.col + 1 &&
        anotherBlock.row == this.row
      ) {
        this.swap(anotherBlock);
        return;
      }
      if (
        dir == "upSwap" &&
        anotherBlock.col == this.col &&
        anotherBlock.row == this.row - 1
      ) {
        this.swap(anotherBlock);
        return;
      }
      if (
        dir == "downSwap" &&
        anotherBlock.col == this.col &&
        anotherBlock.row == this.row + 1
      ) {
        this.swap(anotherBlock);
        return;
      }
    }
  }

  chooseDir() {
    const result = [[], []];
    if (this.col != 0) {
      if (blocksLocation[this.row][this.col - 1] == 0) {
        result[0].push("left");
        if (this.col > this.targetCol) {
          result[0].push("left", "left", "left");
        }
      } else {
        result[1].push("leftSwap");
      }
    }
    if (this.col != segX - 1) {
      if (blocksLocation[this.row][this.col + 1] == 0) {
        result[0].push("right");
        if (this.col < this.targetCol) {
          result[0].push("right", "right", "right");
        }
      } else {
        result[1].push("rightSwap");
      }
    }
    if (this.row != 0) {
      if (blocksLocation[this.row - 1][this.col] == 0) {
        result[0].push("up");
        if (this.row > this.targetRow) {
          result[0].push("up", "up", "up");
        }
      } else {
        result[1].push("upSwap");
      }
    }
    if (this.row != segY - 1) {
      if (blocksLocation[this.row + 1][this.col] == 0) {
        result[0].push("down");
        if (this.row < this.targetRow) {
          result[0].push("down", "down", "down");
        }
      } else {
        result[1].push("downSwap");
      }
    }
    // return random(result);
    if (random() < 0.9) {
      return random(result[0]);
    } else {
      return random(result[1]);
    }
  }
}


