let targetLocation;
let blocksLocation;

function preload() {
  font = loadFont("https://openprocessing.org/sketch/2308776/files/BoutiqueBitmap9x9_1.9.ttf");

}

function setup() {
  createCanvas(windowWidth, windowHeight);
	paddingX = height * 0.1
  textFont(font);
	initGrid();  
}

function draw() {
	background(bg_color);
	for(let block of blocks){
		block.draw()
		if(random()<t/2000){
			block.move();
		}

		if(debugView)block.showTarget()
	}
	if(debugView)showGrid()

	t++
}

function initGrid(){
	t = 0;
	blocks = [];
	targetLocation = textToArray(textInput);
	currentPalette = palettes[palettesNames.indexOf(flag_palette)];
	// print(targetLocation)
	blocksLocation = []
  for (let i=0;i<targetLocation.length;i++) {
		let a = []
		for(let j=0;j<targetLocation[0].length;j++){
			a.push(0)
		}
		blocksLocation.push(a)
  }
  // print(blocksLocation);
  initLocation(targetLocation.count);
	// print(targetLocation)
}

function showGrid(){
	push()
	for(let i=0;i<segX;i++){
		for(let j=0;j<segY;j++){
			const x = map(i,0,segX,paddingX,width-paddingX)
			const y = map(j,0,segY,paddingY,height-paddingY)
			const w = (width-paddingX*2)/segX
			const h = (height-paddingY*2)/segY
			noFill()
			stroke(100)
			rect(x,y,w,h)
		}
	}
	pop()
}

function updateLocation() {
  for (let i = 0; i < segY; i++) {
    for (let j = 0; j < segX; j++) {
      blocksLocation[i][j] = 0;
    }
  }
  for (let block of blocks) {
    blocksLocation[block.row][block.col] = 1;
  }
}

function initLocation(amount) {
  let count = 0;
	segX = targetLocation[0].length;
	segY = targetLocation.length;
	gridSize = (width - paddingX*2)/segX
	paddingY = (height - gridSize * segY)/2
  while (count < amount) {
    let randomRow = floor(random(segY));
    let randomCol = floor(random(segX));
		// print(randomRow)
		// print(randomCol)
    if (blocksLocation[randomRow][randomCol] == 0) {
      blocksLocation[randomRow][randomCol] = 1;
      blocks.push(new Block(randomRow, randomCol, count));
      count++;
    }
  }

	let i=0;
	for (let row = 0; row < segY; row++) {
    for (let col = 0; col < segX; col++) {
      if (targetLocation[row][col] == 1) {
        blocks[i].targetRow = row;
        blocks[i].targetCol = col;
        i++;
      }
    }
  }
}

function textToArray(t) {
  push();
  textSize(100);
  const tWidth = textWidth(t);
  // let temp = createGraphics(tWidth, 100);
  background(255);
  noStroke();
  fill(0);
  textAlign(LEFT, TOP);
  textSize(100);
  text(t, 0, 0);
  const result = [];
  let count = 0;
  for (let i = 0; i < 11; i++) {
    const a = [];
    for (let j = 0; j * 10 < tWidth; j++) {
      if (get(j * 10 + 5, i * 10 + 5)[0] == 0) {
        a.push(1);
        count++;
      } else {
        a.push(0);
      }
    }
    result.push(a);
  }
  pop();

  result.count = count;
  return result;
}

function buttonPressed(variableName){
	if(variableName==="applySetting"){
		initGrid()
	}
	if(variableName==="screenShot"){
		save(`${textInput}_${minute()}${second()}`)
	}
}

function keyPressed(){
	if(key === "s"){
		save(`${textInput}_${minute()}${second()}`)
	}
	if(key === "h"){
		noCursor()
	}
}

